#!/usr/bin/env bash
jlink_version="0.1.1"

if [ "$EUID" -ne 0 ]; then
    echo -e "\033[0;31mError\033[0m: You don't have permission. Please run with sudo."
    exit 1
fi

clear
to_install=()

spinner() {
    local task_name="$1"
    local task_function="$2"
    local pid
    local spin=('⠋' '⠙' '⠹' '⠸' '⠼' '⠴' '⠦' '⠧' '⠇' '⠏')
    local temp_file=$(mktemp)
    
    local GREEN='\033[0;32m'
    local RED='\033[0;31m'
    local NC='\033[0m' 
    
    tput civis  

    $task_function > "$temp_file" 2>&1 &
    pid=$!
    

    local term_width=$(tput cols)
    local max_task_width=$((term_width - 10)) 
    
    if [ ${#task_name} -gt $max_task_width ]; then
        task_name="${task_name:0:$((max_task_width-3))}..."
    fi
    
    printf "%-*s" "$max_task_width" "$task_name"
    local i=0
    while kill -0 $pid 2>/dev/null; do
        printf "\r%-*s[%s]" "$max_task_width" "$task_name" "${spin[i]}"
        i=$(( (i+1) % ${#spin[@]} ))
        sleep 0.2
    done
    
    wait $pid
    local status=$?
    
    if [ $status -eq 0 ] || [ $status -eq 27 ]; then
        printf "\r%-*s[${GREEN}✓${NC}]\n" "$max_task_width" "$task_name"
    else
        printf "\r%-*s[${RED}✗${NC}]\n" "$max_task_width" "$task_name"
        local error_message=$(cat "$temp_file")
        if [ -n "$error_message" ]; then
            echo -e "${RED}Error:${NC} $error_message"
        else
            echo -e "${RED}Error:${NC} An unknown error occurred."
        fi
        exit 2
    fi
    
    rm "$temp_file"

    return $status
}

trap 'tput cnorm' EXIT

# Source os-release once for all functions
if [[ -f /etc/os-release ]]; then
    . /etc/os-release
fi

# Distro family detection using both $ID and $ID_LIKE
is_debian_based() {
    [[ "$ID" =~ ^(ubuntu|debian|linuxmint|devuan|zorin|pop|elementary|neon|kali|raspbian)$ ]] || \
    [[ "$ID_LIKE" == *"debian"* ]] || [[ "$ID_LIKE" == *"ubuntu"* ]]
}
is_rhel_based() {
    [[ "$ID" =~ ^(fedora|centos|rhel|rocky|alma)$ ]] || \
    [[ "$ID_LIKE" == *"fedora"* ]] || [[ "$ID_LIKE" == *"rhel"* ]]
}
is_arch_based() {
    [[ "$ID" =~ ^(arch|manjaro|endeavouros|garuda)$ ]] || \
    [[ "$ID_LIKE" == *"arch"* ]]
}

check_dependencies() {

    command_exists() {
        command -v "$1" &>/dev/null
    }

    library_exists() {
        local lib="$1"

        if is_debian_based; then
            dpkg -l | grep -qw "$lib"
            return $?
        elif is_rhel_based; then
            rpm -q "$lib"
            return $?
        elif is_arch_based; then
            pacman -Qs "$lib" >/dev/null
            return $?
        else
            echo "Unsupported distribution: $ID (ID_LIKE=$ID_LIKE)"
            return 1
        fi
    }

    local temp_to_install=()

    for cmd in xxd curl git; do
        if ! command_exists "$cmd"; then
            temp_to_install+=("$cmd")
        fi
    done

    for lib in libcurl4 libasound2; do
        if is_debian_based; then
            pkg="$lib"
        elif is_rhel_based; then
            if [[ "$lib" == "libcurl4" ]]; then
                pkg="libcurl"
            elif [[ "$lib" == "libasound2" ]]; then
                pkg="alsa-lib"
            fi
        elif is_arch_based; then
            if [[ "$lib" == "libcurl4" ]]; then
                pkg="curl"
            elif [[ "$lib" == "libasound2" ]]; then
                pkg="alsa-lib"
            fi
        else
            echo "Unsupported distribution: $ID (ID_LIKE=$ID_LIKE)"
            continue
        fi

        if ! library_exists "$pkg"; then
            temp_to_install+=("$pkg")
        fi
    done

    if [ ${#temp_to_install[@]} -ne 0 ]; then
        printf "%s\n" "${temp_to_install[@]}" > /tmp/to_install_list
    fi

    return 0
}

installing_dependencies() {
    local to_install=()
    mapfile -t to_install < /tmp/to_install_list

    # Update package list and set package manager based on the distribution
    if is_debian_based; then
        apt-get update
        package_manager="apt-get"
        install_cmd="install -y"
    elif [[ "$ID" == "fedora" ]]; then
        dnf check-update
        package_manager="dnf"
        install_cmd="install -y"
    elif is_rhel_based; then
        yum check-update
        package_manager="yum"
        install_cmd="install -y"
    elif is_arch_based; then
        pacman -Sy
        package_manager="pacman"
        install_cmd="-S --noconfirm"
    else
        echo "Unsupported distribution: $ID (ID_LIKE=$ID_LIKE)"
        return 1
    fi

    # Install packages
    for pkg in "${to_install[@]}"; do
        if ! $package_manager $install_cmd "$pkg" >/dev/null 2>&1; then
            echo "Failed to install $pkg" >&2
            rm -f /tmp/to_install_list
            return 1
        fi
    done

    rm -f /tmp/to_install_list
    return 0
}

check_jabraSDK(){

    if [ -d  "/usr/lib/jabra" ]; then
        return 0
    fi

    echo "jabraSDK is not installed"
    return 27
}


installing_jabraSDK() {
    MD5_ORIGINAL="5092ca68e1b6081de35ccd001f2d974f"
    mkdir -p /usr/lib/jabra

   echo "$libjabraSo" | xxd -r -p > /usr/lib/jabra/libjabra.so

    ln -rs /usr/lib/jabra/libjabra.so /usr/lib/jabra/libjabra.so.1

    MD5_GENERATED=$(md5sum "/usr/lib/jabra/libjabra.so" | awk '{print $1}')
    if [ "$MD5_ORIGINAL" != "$MD5_GENERATED" ]; then
        echo "Checksum mismatch! libjabra.so may be corrupted."
        exit 2
    fi

    echo "/usr/lib/jabra" | sudo tee /etc/ld.so.conf.d/jabra.conf
    ldconfig

    return 0
}

setup_udev() {

    # Create udev rule for Jabra devices using TAG+="uaccess" (systemd-logind)
    # This grants device access to the physically logged-in user without group membership
    echo 'ATTRS{idVendor}=="0b0e", TAG+="uaccess"' | sudo tee /etc/udev/rules.d/99-jabra.rules > /dev/null

    # Reload udev rules
    udevadm control --reload

    # Trigger the rule to apply immediately
    udevadm trigger

    return 0
}

installing_jlink(){
    if ! curl -sf -L -o /usr/local/bin/jlink "https://github.com/Watchdog0x/jLink/releases/download/${jlink_version}/jLink"; then
        echo "Failed to download jLink binary. Check your internet connection and that release v${jlink_version} exists."
        return 1
    fi
    # Verify the downloaded file is an ELF binary (not a 404 HTML page)
    if ! file /usr/local/bin/jlink | grep -q ELF; then
        echo "Downloaded file is not a valid binary. The release asset may be missing."
        rm -f /usr/local/bin/jlink
        return 1
    fi
    chmod +x /usr/local/bin/jlink
    return 0
}

main() { 

    printf "Installering jLink \033[0;32mv%s\033[0m\n\n" "$jlink_version"

    spinner "Checking dependencies" check_dependencies
    
    if [ -s /tmp/to_install_list ]; then
        mapfile -t to_install < /tmp/to_install_list
        spinner "Installing dependencies: ${to_install[*]}" installing_dependencies
    fi

    spinner "Checking jabraSDK installed" check_jabraSDK
    if [ $? -eq 27 ]; then
        spinner "Installing jabraSDK" installing_jabraSDK
    fi

    if [ -c /dev/tty ]; then
        read -p "Do you want to run jLink without root privileges? (y/n): " response < /dev/tty
    else
        echo "No terminal available for interactive prompt. Skipping udev setup."
        echo "Run the installer interactively or manually set up udev rules."
        response="n"
    fi
    if [[ "$response" =~ ^[Yy]$ ]]; then
        spinner "Setting up udev rule for Jabra devices" setup_udev
    fi

    spinner "Installing jlink" installing_jlink

    printf "\nInstallation completed successfully!\n"
}


libjabraSo=""

main
